with DepartmentStats as (select dept_id, count(*) as total_count, sort_array(collect_set(level)) as level_list from employees where length(email) > 7 group by dept_id) select d.id, d.location, D.total_count, D.level_list from departments d inner join DepartmentStats D on d.id = D.dept_id where D.total_count >= 9 order by total_count
